### 3. CODIFICAÇÃO EM JAVA

```java
import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;

public class Main {

    static class Edge implements Comparable<Edge> {
        int u, v, weight;

        Edge(int u, int v, int weight) {
            this.u = u;
            this.v = v;
            this.weight = weight;
        }

        @Override
        public int compareTo(Edge o) {
            // Ordem decrescente de capacidade para Maximum Spanning Tree
            return Integer.compare(o.weight, this.weight);
        }
    }

    static class TreeEdge {
        int to, weight;

        TreeEdge(int to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class DSU {
        int[] parent;

        DSU(int n) {
            parent = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]);
        }

        boolean union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
                return true;
            }
            return false;
        }
    }

    // Variáveis para a árvore e Binary Lifting
    static ArrayList<TreeEdge>[] adj;
    static int[][] up;
    static int[][] minW;
    static int[] depth;
    static final int LOGN = 18; // 2^17 = 131072 > 100000

    static void dfs(int u, int p, int d, int w) {
        depth[u] = d;
        up[u][0] = p;
        minW[u][0] = w;

        for (int k = 1; k < LOGN; k++) {
            up[u][k] = up[up[u][k - 1]][k - 1];
            minW[u][k] = Math.min(minW[u][k - 1], minW[up[u][k - 1]][k - 1]);
        }

        for (TreeEdge edge : adj[u]) {
            if (edge.to != p) {
                dfs(edge.to, u, d + 1, edge.weight);
            }
        }
    }

    static int query(int u, int v) {
        int ans = Integer.MAX_VALUE;

        if (depth[u] < depth[v]) {
            int tmp = u;
            u = v;
            v = tmp;
        }

        // Subir o nó mais profundo até que ambos estejam no mesmo nível
        for (int k = LOGN - 1; k >= 0; k--) {
            if (depth[u] - (1 << k) >= depth[v]) {
                ans = Math.min(ans, minW[u][k]);
                u = up[u][k];
            }
        }

        if (u == v) return ans;

        // Subir simultaneamente até o LCA
        for (int k = LOGN - 1; k >= 0; k--) {
            if (up[u][k] != up[v][k]) {
                ans = Math.min(ans, minW[u][k]);
                ans = Math.min(ans, minW[v][k]);
                u = up[u][k];
                v = up[v][k];
            }
        }

        // Arestas finais conectando ao LCA
        ans = Math.min(ans, minW[u][0]);
        ans = Math.min(ans, minW[v][0]);

        return ans;
    }

    // Fast I/O para leitura eficiente dos dados
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException();
                }
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int b = scanner.nextInt();

        Edge[] edges = new Edge[b];
        for (int i = 0; i < b; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();
            edges[i] = new Edge(u, v, w);
        }

        // Kruskal para construir a Maximum Spanning Tree
        Arrays.sort(edges);
        DSU dsu = new DSU(n);

        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        int edgesCount = 0;
        for (int i = 0; i < b; i++) {
            Edge e = edges[i];
            if (dsu.union(e.u, e.v)) {
                adj[e.u].add(new TreeEdge(e.v, e.weight));
                adj[e.v].add(new TreeEdge(e.u, e.weight));
                edgesCount++;
                if (edgesCount == n - 1) break;
            }
        }

        // Inicialização para Binary Lifting
        up = new int[n + 1][LOGN];
        minW = new int[n + 1][LOGN];
        depth = new int[n + 1];

        // dfs enraizada no nó 1
        dfs(1, 1, 0, Integer.MAX_VALUE);

        int c = scanner.nextInt();
        for (int i = 0; i < c; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            out.println(query(x, y));
        }

        out.flush();
    }
}
```

